var doc = Document;
// Goal: a straight stair from the lowest level to the one above it.

// 1. Base and top levels: the two lowest levels of the document (created with Level.Create when a
//    project lacks them).
Autodesk.Revit.DB.Level l1 = null, l2 = null;
foreach (Autodesk.Revit.DB.Level lv in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (l1 == null || lv.Elevation < l1.Elevation) { l2 = l1; l1 = lv; }
  else if (l2 == null || lv.Elevation < l2.Elevation) { l2 = lv; }
}
if (l1 == null || l2 == null) { throw new System.Exception("two levels are needed"); }

// 2. Start the edit scope at TOP LEVEL, with no block open: Start() opens Revit's own stairs edit
//    mode and needs the document not modifiable. It returns the new Stairs element's id.
var scope = new Autodesk.Revit.DB.StairsEditScope(doc, "how-to straight stair");
var stairsId = scope.Start(l1.Id, l2.Id);

// 3. Build the run INSIDE a block. The run's path is a line in plan; Center justification puts the
//    run's centreline on it. Landings and more runs go in the same block.
Connector.WithTransaction(doc, () => {
  var path = Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 0, 0), new Autodesk.Revit.DB.XYZ(20, 0, 0));
  Autodesk.Revit.DB.Architecture.StairsRun.CreateStraightRun(doc, stairsId, path, Autodesk.Revit.DB.Architecture.StairsRunJustification.Center);
});

// 4. Commit BETWEEN blocks. Commit closes the edit mode and commits its own transaction; while a
//    connector block is open it throws 'EditScope cannot be closed' (script-target-must-not-be-modifiable),
//    and the run above was silently discarded. The preprocessor swallows Revit's warnings (e.g.
//    riser count outside the type's range), which would otherwise block the commit.
scope.Commit(new SwallowWarnings());

// 5. Verify: the stairs exists with one run and a non-zero riser count, and the document is no
//    longer in edit mode. An empty stairs (no risers) means the run was never built.
var stairs = doc.GetElement(stairsId) as Autodesk.Revit.DB.Architecture.Stairs;
var runCount = stairs != null ? stairs.GetStairsRuns().Count : -1;
var risers = stairs != null ? stairs.ActualRisersNumber : -1;
return new { stairsId = stairsId.Value, runCount, risers, baseLevel = l1.Name, topLevel = l2.Name, inEditMode = doc.IsInEditMode(), ok = runCount == 1 && risers > 0 && !doc.IsInEditMode() };

class SwallowWarnings : Autodesk.Revit.DB.IFailuresPreprocessor {
  public Autodesk.Revit.DB.FailureProcessingResult PreprocessFailures(Autodesk.Revit.DB.FailuresAccessor a) {
    a.DeleteAllWarnings();
    return Autodesk.Revit.DB.FailureProcessingResult.Continue;
  }
}
